def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    current_time = 0

    def is_expired(write_time, current_time):
        return current_time >= write_time + ttl

    def remove_expired(current_time):
        # Remove all expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if is_expired(write_time, current_time):
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            current_time = t
            remove_expired(current_time)

            # If key exists, remove it (to update its position)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict least recently used
            elif len(cache) >= capacity:
                # Remove the first (least recently used) item
                cache.popitem(last=False)

            # Add the new entry
            cache[key] = (value, t)
            # Move to end (most recently used)
            cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            current_time = t
            remove_expired(current_time)

            if key in cache:
                value, write_time = cache[key]
                # Make it most recently used
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

